// Postiz renvoie la liste des comptes connectes. On lit les identifiants
// A L EXECUTION plutot que de les figer dans le code : reconnecter un
// compte dans Postiz change son id, et un id perime echoue en silence.
const integrations = $input.all().map(i => i.json).filter(j => j && j.id);

const typeDe = (j) => String(j.identifier || j.providerIdentifier || j.provider || '');
const chercher = (motif) => integrations.find(j => typeDe(j).toLowerCase().indexOf(motif) !== -1);

const tiktok = chercher('tiktok');
const youtube = chercher('youtube');

// Postiz distingue 'linkedin' (profil personnel) et 'linkedin-page'
// (page entreprise) : deux discriminateurs differents, et un __type qui
// ne correspond pas retombe sur des reglages VIDES sans lever d erreur.
// On prefere donc la page si les deux sont connectees, et on renvoie le
// type declare par l API, jamais une valeur devinee.
const linkedin = integrations.find(j => typeDe(j).toLowerCase() === 'linkedin-page')
              || chercher('linkedin');

if (!linkedin) {
  throw new Error('Aucune integration LinkedIn dans Postiz. Comptes vus : '
    + integrations.map(j => typeDe(j) + ' / ' + j.name).join(', '));
}

return [{ json: {
  tiktokId: tiktok ? tiktok.id : null,
  tiktokType: tiktok ? typeDe(tiktok) : null,
  youtubeId: youtube ? youtube.id : null,
  linkedinId: linkedin.id,
  linkedinType: typeDe(linkedin),
  linkedinNom: linkedin.name
} }];

const dossiers = $input.all().filter(i => i.json && i.json.id);
if (dossiers.length === 0) {
  return [{ json: { hasContent: false } }];
}

// Ordre de PRODUCTION, pas alphabetique. Le pipeline fait tourner les
// huit familles de sujets ; trier par nom regrouperait les sujets par
// premiere lettre et detruirait cette alternance a la publication.
dossiers.sort((a, b) => {
  const da = String(a.json.createdTime || '');
  const db = String(b.json.createdTime || '');
  if (da && db && da !== db) { return da.localeCompare(db); }
  return String(a.json.name).localeCompare(String(b.json.name), undefined, { numeric: true });
});

const d = dossiers[0].json;
return [{ json: { hasContent: true, folderId: d.id, folderName: d.name } }];

// 22:00 Paris : cette ligne ne doit pas marcher sur les creneaux de la
// ligne des modules (12:30 / 18:00 / 20:30), sinon les deux se font
// concurrence sur le meme fil le meme jour.
const HEURE = 22;
const MINUTE = 0;

const fichiers = $input.all();
const src = $('Choisir le sujet du jour').first().json;
const reseaux = $('Resoudre les reseaux').first().json;

const trouver = (nom) => {
  const f = fichiers.find(x => String(x.json.name) === nom);
  return f ? f.json.id : null;
};

const videoId = trouver('video.mp4');
const metaId = trouver('video.json');
if (!videoId || !metaId) {
  throw new Error('video.mp4 ou video.json manquant dans ' + src.folderName);
}

const maintenant = $now.setZone('Europe/Paris');
const vise = maintenant.set({ hour: HEURE, minute: MINUTE, second: 0, millisecond: 0 });
const quand = vise <= maintenant ? vise.plus({ days: 1 }) : vise;

return [{ json: Object.assign({}, reseaux, {
  videoId: videoId,
  metaId: metaId,
  quandUtc: quand.toUTC().toISO(),
  quandParis: quand.toFormat('dd/MM/yyyy HH:mm'),
  folderId: src.folderId,
  folderName: src.folderName
}) }];

const ligne = $('Preparer la publication').first().json;
const upload = $('Envoyer la video a Postiz').first().json;
const meta = $('Lire les metadonnees').first().json.meta;

if (!upload || !upload.id || !upload.path) {
  throw new Error("Reponse inattendue de Postiz a l upload : " + JSON.stringify(upload));
}

// Bug amont : l upload renvoie parfois un chemin en .mp4s, que la
// creation de post refuse ensuite.
const brut = String(upload.path);
const chemin = brut.slice(-5) === '.mp4s' ? brut.slice(0, -1) : brut;
const media = { id: upload.id, path: chemin };

const SAUT = String.fromCharCode(10);
const accroche = String(meta.legende || '').trim();
const sujet = String(meta.sujet || '').trim();
const notion = String(meta.notion || '').trim();
const url = String(meta.url || '').trim();
const aUnModule = Boolean(meta.module);

const tags = (meta.hashtags || []).map(t => {
  const s = String(t).trim();
  return s.charAt(0) === '#' ? s : '#' + s;
});

// TikTok : un lien n y est pas cliquable, inutile d en mettre un.
const legendeTikTok = [accroche, tags.join(' ')]
  .filter(m => m.length > 0).join(SAUT + SAUT).slice(0, 2200);

// YouTube : le lien EST cliquable.
const descriptionYouTube = [
  accroche,
  url ? "Le cours complet, gratuitement :" + SAUT + url : '',
  (tags.join(' ') + ' #Shorts').trim()
].filter(m => m.length > 0).join(SAUT + SAUT).slice(0, 4900);

// LinkedIn page entreprise : le public n est PAS celui de TikTok. La
// video tutoie un ado ; ici on s adresse a des parents et des
// enseignants. On garde l accroche mais on explique la demarche autour,
// et on met le lien en clair — c est le seul des trois reseaux ou il
// ramene vraiment du trafic.
// Un sujet est souvent formule en question et porte deja son « ? » :
// y coller un point donnerait « ... plus a manger ?. » dans le texte
// publie sur la page.
const ponctuer = (s) => (/[.!?…]$/.test(s) ? s : s + '.');

const cadrage = "Chaque jour, une notion de mathématiques vue depuis ce qui occupe vraiment les adolescents."
  + (sujet ? " Aujourd'hui : " + ponctuer(sujet) : '')
  + (notion ? " La notion qui se cache derrière : " + ponctuer(notion) : '');

const lien = aUnModule
  ? "Le module complet, gratuit et sans inscription :" + SAUT + url
  : "Tous les cours, gratuits et sans inscription :" + SAUT + url;

const texteLinkedIn = [accroche, cadrage, lien,
  "#Mathématiques #Éducation #Pédagogie #SparkLearning"]
  .filter(m => m.length > 0).join(SAUT + SAUT).slice(0, 2900);

const posts = [];

if (ligne.tiktokId) {
  posts.push({
    integration: { id: ligne.tiktokId },
    value: [{ content: legendeTikTok, image: [media] }],
    settings: {
      __type: ligne.tiktokType,
      title: accroche.slice(0, 90),
      privacy_level: 'PUBLIC_TO_EVERYONE',
      duet: true,
      stitch: true,
      comment: true,
      autoAddMusic: 'no',
      brand_content_toggle: false,
      brand_organic_toggle: false,
      video_made_with_ai: true,
      content_posting_method: 'DIRECT_POST'
    }
  });
}

if (ligne.youtubeId) {
  // YouTube exige un titre de 2 a 100 caracteres : repli si vide.
  posts.push({
    integration: { id: ligne.youtubeId },
    value: [{ content: descriptionYouTube, image: [media] }],
    settings: {
      __type: 'youtube',
      title: accroche.slice(0, 100) || 'Spark Learning',
      type: 'public',
      selfDeclaredMadeForKids: 'no'
    }
  });
}

posts.push({
  integration: { id: ligne.linkedinId },
  value: [{ content: texteLinkedIn, image: [media] }],
  settings: { __type: ligne.linkedinType }
});

return [{ json: {
  body: { type: 'schedule', date: ligne.quandUtc, shortLink: false, tags: [], posts: posts },
  reseaux: posts.length,
  quandParis: ligne.quandParis,
  linkedinNom: ligne.linkedinNom,
  linkedinType: ligne.linkedinType,
  texteLinkedIn: texteLinkedIn
} }];
